TLM.f("Sancti/07-01",{"officium":"Pretiosissimi Sanguinis Domini Nostri Jesu Christi","rule":["Gloria","Credo","Prefatio=Quad5;"],"sections":{"Introitus":[{"k":"ref","la":"Apoc 5:9-10"},{"k":"text","la":"Redemísti nos, Dómine, in sánguine tuo, ex omni tribu et lingua et pópulo et natióne: et fecísti nos Deo nostro regnum."},{"k":"ref","la":"Ps 88:2"},{"k":"text","la":"Misericórdias Dómini in ætérnum cantábo: in generatiónem et generatiónem annuntiábo veritátem tuam in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Redemísti nos, Dómine, in sánguine tuo, ex omni tribu et lingua et pópulo et natióne: et fecísti nos Deo nostro regnum."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui unigénitum Fílium tuum mundi Redemptórem constituísti, ac ejus Sánguine placári voluísti: concéde, quǽsumus, salútis nostræ prétium sollémni cultu ita venerári, atque a præséntis vitæ malis ejus virtúte deféndi in terris; ut fructu perpétuo lætémur in cœlis."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos."},{"k":"ref","la":"Hebr 9:11-15"},{"k":"text","la":"Fratres: Christus assístens Póntifex futurórum bonórum, per ámplius et perféctius tabernáculum non manufáctum, id est, non hujus creatiónis: neque per sánguinem hircórum aut vitulórum, sed per próprium sánguinem introívit semel in Sancta, ætérna redemptióne invénta. Si enim sanguis hircórum et taurórum, et cinis vítulæ aspérsus, inquinátos sanctíficat ad emundatiónem carnis: quanto magis sanguis Christi, qui per Spíritum Sanctum semetípsum óbtulit immaculátum Deo, emundábit consciéntiam nostram ab opéribus mórtuis, ad serviéndum Deo vivénti? Et ídeo novi Testaménti mediátor est: ut, morte intercedénte, in redemptiónem eárum prævaricatiónum, quæ erant sub prióri Testaménto, repromissiónem accípiant, qui vocáti sunt ætérnæ hereditátis, in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"1 Joann 5:6-8"},{"k":"text","la":"Hic est, qui venit per aquam et sánguinem, Jesus Christus: non in aqua solum, sed in aqua et sánguine."},{"k":"text","la":"Tres sunt, qui testimónium dant in cœlo: Pater, Verbum et Spíritus Sanctus; et hi tres unum sunt. Et tres sunt, qui testimónium dant in terra: Spíritus, aqua et sanguis: et hi tres unum sunt. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"1 Joann 5:9"},{"k":"text","la":"Si testimónium hóminum accípimus, testimónium Dei majus est. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Apoc 5:9"},{"k":"text","la":"Dignus es, Dómine, accípere librum, et aperíre signácula ejus: quóniam occísus es, et redemísti nos Deo in sánguine tuo."},{"k":"ref","la":"Exod 12:13"},{"k":"text","la":"Erit autem sanguis vobis in signum: et vidébo sánguinem, et transíbo vos: nec erit in vobis plaga dispérdens. Allelúja."}],"Tractus":[{"k":"ref","la":"Ephes 1:6-8"},{"k":"text","la":"Gratificávit nos Deus in dilécto Fílio suo, in quo habémus redemptiónem per sánguinem ejus."},{"k":"text","la":"Remissiónem peccatórum, secúndum divítias grátiæ ejus, quæ superabundávit in nobis.","mark":"V"},{"k":"ref","la":"Rom 3:24-25"},{"k":"text","la":"Justificáti gratis per grátiam ipsíus, per redemptiónem, quæ est in Christo Jesu."},{"k":"text","la":"Quem propósuit Deus propitiatiónem per fidem in sánguine ipsíus.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 19:30-35"},{"k":"text","la":"In illo témpore: Cum accepísset Jesus acétum, dixit: Consummátum est. Et inclináto cápite trádidit spíritum. Judæi ergo - quóniam Parascéve erat -, ut non remanérent in cruce córpora sábbato - erat enim magnus dies ille sábbati -, rogavérunt Pilátum, ut frangeréntur eórum crura et tolleréntur. Venérunt ergo mílites: et primi quidem fregérunt crura et altérius, qui crucifíxus est cum eo. Ad Jesum autem cum venissent, ut vidérunt eum jam mórtuum, non fregérunt ejus crura, sed unus mílitum láncea latus ejus apéruit, et contínuo exívit sanguis et aqua. Et qui vidit, testimónium perhíbuit; et verum est testimónium ejus."}],"Offertorium":[{"k":"ref","la":"1 Cor 10:16"},{"k":"text","la":"Calix benedictiónis, cui benedícimus, nonne communicátio sánguinis Christi est? et panis, quem frángimus, nonne participátio córporis Dómini est?"}],"Secreta":[{"k":"text","la":"Per hæc divína mystéria, ad novi, quǽsumus, Testaménti mediatórem Jesum accedámus: et super altária tua, Dómine virtútum, aspersiónem sánguinis mélius loquéntem, quam Abel, innovémus."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Hebr 9:28"},{"k":"text","la":"Christus semel oblátus est ad multórum exhauriénda peccáta: secúndo sine peccáto apparébit exspectántibus se in salútem."}],"Postcommunio":[{"k":"text","la":"Ad sacram, Dómine, mensam admíssi, háusimus aquas in gáudio de fóntibus Salvatóris: sanguis ejus fiat nobis, quǽsumus, fons aquæ in vitam ætérnam saliéntis:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"5b1f12b7a833fd93":{"t":"Otk 5, 9-10, Ps 88, 2\n(Otk 5, 9-10) Otkupio si nas, Gospodine, svojom krvi od svakog plemena i jezika, od svakog puka i naroda, i učinio si nas kraljevstvom za Boga našega. (Ps 88, 2) Milosrdna ću djela Gospodnja pjevati u vijeke; svojim ću ustima navješćivati tvoju vjernost kroz sve naraštaje.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Otk 5, 9-10) Otkupio si nas, Gospodine, svojom krvi od svakog plemena i jezika, od svakog puka i naroda, i učinio si nas kraljevstvom za Boga našega."},"c2e67b5ab31d07c5":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si jedinorođenoga Sina svoga postavio za Spasitelja svijeta i odredio da ti njegova Krv bude na pomirbu, podaj, molimo, da cijenu našega spasenja svečanom službom tako štujemo i da nas njezina moć tako štiti od zla u ovom životu, da joj vječni plod uživamo na nebu.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a98a57abcad1ed96":{"t":"Heb 9, 11-15\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo: Krist veliki svećenik budućih dobara, nakon što je prešao kroz veći i savršeniji šator, koji nije učinjen rukama, to jest ne pripada ovom svijetu, ušao je, jednom zauvijek, u vječno svetište, ne krvlju jaraca ili junaca, nego vlastitom krvlju, pošto nam je stekao vječni otkup. Ako krv jaraca i volova i posipanje pepelom junice posvećuje okaljane dajući njihovu tijelu zakonsku čistoću, koliko će više krv Krista, koji samoga sebe neokaljana Bogu prinese po Svetom Duhu, očistiti našu savjest od mrtvih djela, da služimo živome Bogu? On je zato posrednik novoga zavjeta, da po smrti, koju je podnio za otkup počinjenih prestupaka u prvom zavjetu, svi izabranici prime obećanu vječnu baštinu u našem Gospodinu Isusu Kristu."},"5198582a7d569854":{"t":"1 Iv 5, 6 i 7-8\nOvaj je došao u vodi i u krvi, ne samo u vođi nego u vodi i u krvi. Trojica svjedoče na nebu: Otac i Riječ i Duh Sveti, i ova trojica su jedno. I troje svjedoči na zemlji: Duh i voda i krv, i ovo je troje jedno.\n\n1 Iv 5, 9\n<i>Aleluja</i>, <i>aleluja</i>.\nAko prihvaćamo svjedočanstvo ljudi, Božje je svjedočanstvo veće. <i>Aleluja</i>."},"412aee8952dd60dc":{"t":"Iv 19, 30-35\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme, kad je Isus okusio ocat, reče: Svršeno je! I nakloni glavu i predade duh. Budući da je bio dan priprave i da tjelesa ne bi ostala na križu u subotu (jer je one subote bio veliki blagdan), Židovi zamole Pilata da im se prebiju noge pa da se skinu. Vojnici dođu i prebiju noge obojici raspetih s Isusom. Ali, kad su došli do Isusa i vidjeli da je već umro. ne prebiju mu noge, nego jedan vojnik kopljem otvori njegova rebra, i odmah poteče krv i voda. Onaj koji je to vidio svjedoči, i njegovo je svjedočanstvo istinito."},"116961e98562829f":{"t":"1 Kor 10, 16\nZar nije blagoslovljeni kalež, koji blagoslivljamo, zajednica krvi Kristove? Zar nije kruh, koji lomimo, zajednica tijela Kristova?"},"58b4546f921afccc":{"t":"Po ovim božanskim otajstvima, molimo, da pristupimo k Isusu, posredniku novoga Zavjeta, i da na tvojim oltarima, Bože svake moći, ponovno poteče krv koja zaziva rječitije nego Abelova.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:"},"69e4ad9c8b3921a6":{"t":"Heb 9, 28\nKrist se žrtvovao jedanput, da uzme grijehe mnogih; drugi će se put pokazati bez grijeha onima koji ga iščekuju za spasenje."},"57fe4b79ce5ae0b1":{"t":"<i>Pomolimo se</i>.\nPripušteni k svetom stolu, Gospodine, u radosti smo crpili vodu iz vrela Spasiteljeva; njegova krv neka nam bude, molimo, vrelo vode koje ključa u vječni život:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
